const MAX_CONTENT_CHARS = 2000;

function buildArticlesBlock(articles) {
  return articles.map(a => {
    const content = (a.content || '').slice(0, MAX_CONTENT_CHARS);
    return `[Fuente: ${a.source_name}]\nTítulo: ${a.title}\nTexto: ${content}`;
  }).join('\n\n');
}

const SCHEMA = `{
  "que_paso": string,
  "por_que_importa": string,
  "impacto": string,
  "hechos_confirmados": string[],
  "interpretaciones": [{"fuente": string, "afirmacion": string}],
  "discrepancias": [{"aspecto": string, "version_por_fuente": {"<nombre_fuente>": string}}],
  "preguntas_abiertas": string[]
}`;

// Solo llegan aquí clusters con source_count >= 2 (filtrados antes de este nodo)
const RULES = `Eres un analista de noticias. Compara cómo distintos medios han cubierto el MISMO acontecimiento, usando ÚNICAMENTE los textos de abajo.

Es muy probable que ya conozcas este suceso (o uno similar) de tu entrenamiento, con datos adicionales que no están en los textos de abajo (cifras de superficie afectada, evacuados, fallecidos, fechas). IGNORA por completo ese conocimiento previo. Compórtate como si esta fuera la única información que existe sobre el hecho.

Ejemplo de lo que NO debes hacer: si ningún texto menciona cuántas hectáreas ha quemado un incendio, NO escribas ninguna cifra de hectáreas, aunque la recuerdes de casos similares. Si un dato no aparece literalmente en alguno de los textos de abajo, omítelo — no lo apliques por analogía ni lo redondees.

Reglas:
- Sé conciso: cada campo de texto son 1-3 frases directas, sin rodeos ni repeticiones. Pero no sacrifiques información necesaria para entender el hecho por acortar demasiado — prioriza que quien lo lea entienda qué pasó y por qué importa, no la brevedad extrema.
- Nada de introducciones ni opiniones propias.
- Diferencia hechos verificables de interpretaciones (juicios de valor, adjetivos calificativos). Una diferencia de precisión entre fuentes sobre el mismo hecho (ej. "misiles" vs "misiles y drones") es una discrepancia factual, no una interpretación.
- Si dos fuentes dan datos distintos del mismo hecho, señálalo en "discrepancias" con la versión de cada fuente.
- "hechos_confirmados" son solo los hechos en los que TODAS las fuentes coinciden.
- Incluye tantos elementos como sean relevantes y estén respaldados por el texto en los arrays ("hechos_confirmados", "interpretaciones", "discrepancias", "preguntas_abiertas") — ni un número arbitrario ni relleno sin sustancia.
- Todos los campos del esquema deben rellenarse con contenido real; ninguno puede quedar vacío.
- JSON válido, sin comas finales.
- Responde SOLO con el JSON final.`;

const items = $input.all();

return items.map(item => {
  const cluster = item.json;
  const articlesBlock = buildArticlesBlock(cluster.articles);

  const prompt = `${RULES}

Esquema exacto de salida (JSON):
${SCHEMA}

Artículos:
${articlesBlock}`;

  return {
    json: {
      cluster_id: cluster.cluster_id,
      article_count: cluster.article_count,
      source_count: cluster.source_count,
      sources: cluster.sources,
      articles: cluster.articles.map(a => ({ title: a.title, link: a.link, source_name: a.source_name, category: a.category })),
      prompt
    }
  };
});

const REQUIRED_FIELDS = [
  'que_paso', 'por_que_importa', 'impacto',
  'hechos_confirmados', 'interpretaciones', 'discrepancias', 'preguntas_abiertas'
];

function stripTrailingCommas(text) {
  // deepseek-r1 y otros modelos suelen dejar comas finales antes de "}" o "]", inválidas en JSON estricto
  return text.replace(/,(\s*[}\]])/g, '$1');
}

function extractJson(raw) {
  // Por si en el futuro se usa un modelo de razonamiento que antepone <think>...</think>
  const withoutThink = raw.replace(/<think>[\s\S]*?<\/think>/i, '').trim();
  const cleaned = stripTrailingCommas(withoutThink);

  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) {
      throw new Error(`No se encontró un JSON válido en la respuesta del LLM. Respuesta cruda (primeros 500 caracteres): ${raw.slice(0, 500)}`);
    }
    const candidate = cleaned.slice(start, end + 1);
    try {
      return JSON.parse(candidate);
    } catch (e2) {
      throw new Error(`JSON extraído no parseable: ${e2.message}. Candidato (primeros 500 caracteres): ${candidate.slice(0, 500)}`);
    }
  }
}

const items = $input.all();

// Cada item se procesa de forma aislada: si uno falla al parsear, se guarda
// como registro de error y el resto del batch sigue su curso — un cluster
// problemático no debe tirar el análisis de los demás.
return items.map((item, idx) => {
  // itemMatching resuelve el item de origen real vía pairedItem, no por posición
  // dentro de esta rama — n8n reindexa desde 0 cada rama de salida (éxito/error),
  // así que una simple posición local aquí apuntaría al cluster equivocado.
  const clusterMeta = $('Build Prompt per Cluster').itemMatching(idx).json;
  const base = {
    cluster_id: clusterMeta.cluster_id,
    source_count: clusterMeta.source_count,
    sources: clusterMeta.sources,
    articles: clusterMeta.articles
  };

  try {
    const raw = item.json.choices?.[0]?.message?.content;
    if (!raw) {
      throw new Error(`Respuesta de Groq sin contenido esperado (choices[0].message.content). Payload recibido: ${JSON.stringify(item.json).slice(0, 500)}`);
    }
    const parsed = extractJson(raw);

    const missing = REQUIRED_FIELDS.filter(f => !(f in parsed));
    if (missing.length > 0) {
      throw new Error(`Faltan campos requeridos en la respuesta del LLM: ${missing.join(', ')}. JSON recibido: ${JSON.stringify(parsed).slice(0, 500)}`);
    }

    return { json: { ...base, analysis: parsed, status: 'ok', error_message: null } };
  } catch (e) {
    return { json: { ...base, analysis: null, status: 'error', error_message: e.message } };
  }
});

// Rama de error de "Call Ollama for Analysis" (onError: continueErrorOutput).
// Un fallo de red/timeout aquí no debe tirar el resto del batch — se registra
// como intento fallido en cluster_analysis y el workflow sigue.
const items = $input.all();

return items.map((item, idx) => {
  // itemMatching resuelve el item de origen real vía pairedItem, no por posición
  // dentro de esta rama — ver mismo comentario en Parse & Validate LLM Response.
  const clusterMeta = $('Build Prompt per Cluster').itemMatching(idx).json;
  const errorMessage =
    item.json?.error?.message ||
    item.json?.error ||
    item.json?.message ||
    `Fallo en la llamada a Ollama sin mensaje de error legible: ${JSON.stringify(item.json).slice(0, 300)}`;

  return {
    json: {
      cluster_id: clusterMeta.cluster_id,
      source_count: clusterMeta.source_count,
      sources: clusterMeta.sources,
      articles: clusterMeta.articles,
      analysis: null,
      status: 'error',
      error_message: String(errorMessage).slice(0, 1000)
    }
  };
});

