// "Get Already-Analyzed Links" corre una sola vez (executeOnce) y devuelve
// un row por link ya cubierto con éxito en las últimas 48h. Aquí se recupera
// la lista real de clusters desde el nodo del filtro de fuentes (no desde
// el input directo, ya que executeOnce reemplaza los items por los suyos).
const analyzedLinks = new Set($input.all().map(item => item.json.link));
const clusters = $('Filter Multi-Source Clusters').all().map(item => item.json);

// Se reprocesa un cluster si tiene AL MENOS un artículo todavía no analizado
// con éxito (ej. una fuente nueva se sumó a un evento ya cubierto). Si TODOS
// sus artículos ya están cubiertos, se salta — ya se generó un análisis para
// exactamente ese conjunto de fuentes.
const unanalyzed = clusters.filter(cluster => {
  const links = cluster.articles.map(a => a.link);
  const allAlreadyAnalyzed = links.every(link => analyzedLinks.has(link));
  return !allAlreadyAnalyzed;
});

return unanalyzed.map(c => ({ json: c }));

// "Check Daily Cap" corre una sola vez (executeOnce) y su output es la fila
// del count, no la lista de clusters. Aquí se recupera la lista real desde
// el nodo anterior para que el resto de la cadena siga trabajando con los
// clusters, no con la fila de conteo.
return $('Filter Unanalyzed Clusters').all();
